head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.init = function() {
    var jsonData = [{
            "col1": "sample1",
            "col2": "sample2_1",
            "col3": "sample3_1",
            "col4": "sample4_1"
        },
        {
            "col1": "sample1",
            "col2": "sample2_1",
            "col3": "sample3_1",
            "col4": "sample4_1"
        },
        {
            "col1": "sample1",
            "col2": "sample2_2",
            "col3": "sample3_1",
            "col4": "sample4_1"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.__isMerged = function() {
    var rows = ((j) => j.length ? j : $('.mf_grid_body_row'))($('.grid_body_row')).not(".w2grid_hidedRow");
    return scwin.__isMergedRow(rows, 0) && scwin.__isMergedRow(rows, 1) && !scwin.__isMergedRow(rows, 2);
}
scwin.__isMergedRow = function(rows, index) {
    var count = 0;
    var tds = scwin.__getJq(rows[index]).find('td');
    var dataColmerged = WebSquare.util.getDataPrefix("colmerged");
    for (var i = 0; i < tds.length; i++) {
        var colMerged = parseInt(scwin.__getJq(tds[i]).attr(dataColmerged));
        if (!index) {
            var hasBB = scwin.__getJq(tds[i]).css("border-bottom-width");
            if (hasBB != "0px") {
                return false;
            }
        } else if (index == 1) {
            if (!colMerged) {
                return false;
            }
        } else {
            if (colMerged) {
                count++;
            }
        }
    }
    if (index == 2) {
        return count != 0;
    }
    return true;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
}
